-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the fluid capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- fluid / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'fluid' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book fluid refused: fluid/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'eceff8a9eaecb5e0fb3f758092b8a532' and fields = '[{"key": "ekene_pb_standing_psia", "tol": 0.05, "unit": "psia", "label": "Standing bubble point at 400 scf/stb", "expected": 1912.1923059028293}, {"key": "ekene_bo_at_designed_rs", "tol": 0.0005, "unit": "rb/stb", "label": "Standing saturated Bo at 400 scf/stb", "expected": 1.2407824121407645}, {"key": "ekene_muod_beal_cp", "tol": 0.0005, "unit": "cp", "label": "Beal dead oil viscosity", "expected": 2.3437444714709295}, {"key": "ekene_z_hy_at_pi", "tol": 0.0005, "unit": "-", "label": "Hall-Yarborough z at 3200 psia", "expected": 0.8577529684232971}, {"key": "ekene_bg_at_pi_rb_scf", "tol": 5E-7, "unit": "rb/scf", "label": "Gas FVF at 3200 psia", "expected": 0.0008633118643757966}, {"key": "ekene_z_correlation_gap_pct", "tol": 0.002, "unit": "percent", "label": "z disagreement, HY against DAK", "expected": -0.3303055462323185}]'::jsonb then 'old'
              when md5(prompt) = '47748bc1218f0c0462c01ad1c93ad1a9' and fields = '[{"key": "ekene_pb_standing_psia", "tol": 0.05, "unit": "psia", "label": "Standing bubble point at 400 scf/stb", "expected": 1912.1923059028293}, {"key": "ekene_bo_at_designed_rs", "tol": 0.0005, "unit": "rb/stb", "label": "Standing saturated Bo at 400 scf/stb", "expected": 1.2407824121407645}, {"key": "ekene_muod_beal_cp", "tol": 0.0005, "unit": "cp", "label": "Beal dead oil viscosity", "expected": 2.3437444714709295}, {"key": "ekene_z_hy_at_pi", "tol": 0.0005, "unit": "-", "label": "Hall-Yarborough z at 3200 psia", "expected": 0.8577529684232971}, {"key": "ekene_bg_at_pi_rb_scf", "tol": 5E-7, "unit": "rb/scf", "label": "Gas FVF at 3200 psia", "expected": 0.0008633118643757966}, {"key": "ekene_z_correlation_gap_pct", "tol": 0.002, "unit": "percent", "label": "z disagreement, HY against DAK", "expected": -0.3303055462323185}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'fluid' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book fluid refused: fluid/beginner matches neither its published form (prompt md5 eceff8a9eaecb5e0fb3f758092b8a532) nor its W1 form (prompt md5 47748bc1218f0c0462c01ad1c93ad1a9), with the fields this file was generated against';
  end if;

  -- fluid / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'fluid' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book fluid refused: fluid/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'bab5f11f6a8a72319499ce75fb15f51e' and fields = '[{"key": "good_oil_c7plus_tc_r", "tol": 0.05, "unit": "degR", "label": "C7+ critical temperature", "expected": 1324.2385574932478}, {"key": "good_oil_untuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Untuned saturation pressure", "expected": 2791.100735294379}, {"key": "good_oil_psat_bias_pct", "tol": 0.02, "unit": "percent", "label": "Saturation pressure above the lab value", "expected": 5.938198064045652}, {"key": "good_oil_untuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Untuned total gas-oil ratio", "expected": 793.8042771796476}, {"key": "good_oil_untuned_sto_api", "tol": 0.05, "unit": "API", "label": "Untuned stock tank gravity", "expected": 31.8056416463794}, {"key": "good_oil_api_bias", "tol": 0.05, "unit": "API", "label": "Gravity minus the lab value", "expected": -8.894358353620603}]'::jsonb then 'old'
              when md5(prompt) = '3f7abe6a61283cb6be5c4066abffda2a' and fields = '[{"key": "good_oil_c7plus_tc_r", "tol": 0.05, "unit": "degR", "label": "C7+ critical temperature", "expected": 1324.2385574932478}, {"key": "good_oil_untuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Untuned saturation pressure", "expected": 2791.100735294379}, {"key": "good_oil_psat_bias_pct", "tol": 0.02, "unit": "percent", "label": "Saturation pressure above the lab value", "expected": 5.938198064045652}, {"key": "good_oil_untuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Untuned total gas-oil ratio", "expected": 793.8042771796476}, {"key": "good_oil_untuned_sto_api", "tol": 0.05, "unit": "API", "label": "Untuned stock tank gravity", "expected": 31.8056416463794}, {"key": "good_oil_api_bias", "tol": 0.05, "unit": "API", "label": "Gravity minus the lab value", "expected": -8.894358353620603}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'fluid' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book fluid refused: fluid/intermediate matches neither its published form (prompt md5 bab5f11f6a8a72319499ce75fb15f51e) nor its W1 form (prompt md5 3f7abe6a61283cb6be5c4066abffda2a), with the fields this file was generated against';
  end if;

  -- fluid / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'fluid' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book fluid refused: fluid/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'a933375039059401c083800fbec99667' and fields = '[{"key": "good_oil_tuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Tuned saturation pressure", "expected": 2632.64216695564}, {"key": "good_oil_tuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Tuned total gas-oil ratio", "expected": 761.7262989883229}, {"key": "good_oil_tuned_sto_api", "tol": 0.05, "unit": "API", "label": "Tuned stock tank gravity", "expected": 38.755039373806255}, {"key": "tuned_splus_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C7+ volume shift", "expected": 0.12266364195926757}, {"key": "tuned_kc1_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C1 to C7+ interaction parameter", "expected": 0.050325447877585576}, {"key": "tuning_ssr_reduction", "tol": 0.05, "unit": "times", "label": "Residual reduction factor", "expected": 23.157104602764026}]'::jsonb then 'old'
              when md5(prompt) = '332a0e7774027e1383ae1316983e822f' and fields = '[{"key": "good_oil_tuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Tuned saturation pressure", "expected": 2632.64216695564}, {"key": "good_oil_tuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Tuned total gas-oil ratio", "expected": 761.7262989883229}, {"key": "good_oil_tuned_sto_api", "tol": 0.05, "unit": "API", "label": "Tuned stock tank gravity", "expected": 38.755039373806255}, {"key": "tuned_splus_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C7+ volume shift", "expected": 0.12266364195926757}, {"key": "tuned_kc1_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C1 to C7+ interaction parameter", "expected": 0.050325447877585576}, {"key": "tuning_ssr_reduction", "tol": 0.05, "unit": "times", "label": "Residual reduction factor", "expected": 23.157104602764026}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'fluid' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book fluid refused: fluid/advanced matches neither its published form (prompt md5 a933375039059401c083800fbec99667) nor its W1 form (prompt md5 332a0e7774027e1383ae1316983e822f), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book fluid: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book fluid refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Produce a black-oil description of the Ekene oil from the correlations the engine carries. The fluid is 32 API with a gas gravity of 0.75 at a reservoir temperature of 180 F, its designed bubble point is 2000 psia, its designed solution gas ratio is 400 scf/stb and its initial pressure is 3200 psia. Report the bubble point Standing''s correlation returns for the DESIGNED 400 scf/stb; the SATURATED formation volume factor Standing returns at that same designed solution gas ratio, with no undersaturated correction applied; the dead oil viscosity Beal''s correlation returns, with no dissolved gas in it; the gas z factor Hall-Yarborough returns at the INITIAL pressure of 3200 psia on Sutton pseudo-criticals; the gas formation volume factor at that pressure on that same z; and the percentage by which the Hall-Yarborough z differs from the Dranchuk-Abou-Kassem z at the same state, taken relative to Dranchuk-Abou-Kassem.',
           fields = '[{"key": "ekene_pb_standing_psia", "tol": 0.05, "unit": "psia", "label": "Standing bubble point at 400 scf/stb", "expected": 1912.1923059028293}, {"key": "ekene_bo_at_designed_rs", "tol": 0.0005, "unit": "rb/stb", "label": "Standing saturated Bo at 400 scf/stb", "expected": 1.2407824121407645}, {"key": "ekene_muod_beal_cp", "tol": 0.0005, "unit": "cp", "label": "Beal dead oil viscosity", "expected": 2.3437444714709295}, {"key": "ekene_z_hy_at_pi", "tol": 0.0005, "unit": "-", "label": "Hall-Yarborough z at 3200 psia", "expected": 0.8577529684232971}, {"key": "ekene_bg_at_pi_rb_scf", "tol": 5E-7, "unit": "rb/scf", "label": "Gas FVF at 3200 psia", "expected": 0.0008633118643757966}, {"key": "ekene_z_correlation_gap_pct", "tol": 0.002, "unit": "percent", "label": "z disagreement, HY against DAK", "expected": -0.3303055462323185}]'::jsonb
     where app_slug = 'fluid' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book fluid refused: fluid/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '47748bc1218f0c0462c01ad1c93ad1a9' and fields = '[{"key": "ekene_pb_standing_psia", "tol": 0.05, "unit": "psia", "label": "Standing bubble point at 400 scf/stb", "expected": 1912.1923059028293}, {"key": "ekene_bo_at_designed_rs", "tol": 0.0005, "unit": "rb/stb", "label": "Standing saturated Bo at 400 scf/stb", "expected": 1.2407824121407645}, {"key": "ekene_muod_beal_cp", "tol": 0.0005, "unit": "cp", "label": "Beal dead oil viscosity", "expected": 2.3437444714709295}, {"key": "ekene_z_hy_at_pi", "tol": 0.0005, "unit": "-", "label": "Hall-Yarborough z at 3200 psia", "expected": 0.8577529684232971}, {"key": "ekene_bg_at_pi_rb_scf", "tol": 5E-7, "unit": "rb/scf", "label": "Gas FVF at 3200 psia", "expected": 0.0008633118643757966}, {"key": "ekene_z_correlation_gap_pct", "tol": 0.002, "unit": "percent", "label": "z disagreement, HY against DAK", "expected": -0.3303055462323185}]'::jsonb) from public.academy_capstones where app_slug = 'fluid' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book fluid refused: fluid/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run an untuned Peng-Robinson model against a published laboratory study and quantify every gap. The fluid is Good Oil Co. Well No. 4 as Core Laboratories reported it: eleven components with a C7+ fraction of molecular weight 218 and specific gravity 0.8515, at a reservoir temperature of 220 F and a measured bubble point of 2634.65 psia. Its optimum separator test ran at 100 psig and 75 F, which is 114.65 psia, to a stock tank at 14.65 psia and 75 F, and measured a total gas-oil ratio of 768 scf/stb, a stock tank gravity of 40.7 API and a formation volume factor of 1.474 rb/stb. Characterize the plus fraction and report the critical temperature it is given in degrees Rankine. Then run the model, WITHOUT tuning anything and WITH the stock tank stage appended to the reported separator stage, and report its saturation pressure at 220 F, the percentage by which that exceeds the measured bubble point, the total gas-oil ratio the separator train produces, the stock tank gravity it produces, and the difference between that gravity and the laboratory''s in API.',
           fields = '[{"key": "good_oil_c7plus_tc_r", "tol": 0.05, "unit": "degR", "label": "C7+ critical temperature", "expected": 1324.2385574932478}, {"key": "good_oil_untuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Untuned saturation pressure", "expected": 2791.100735294379}, {"key": "good_oil_psat_bias_pct", "tol": 0.02, "unit": "percent", "label": "Saturation pressure above the lab value", "expected": 5.938198064045652}, {"key": "good_oil_untuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Untuned total gas-oil ratio", "expected": 793.8042771796476}, {"key": "good_oil_untuned_sto_api", "tol": 0.05, "unit": "API", "label": "Untuned stock tank gravity", "expected": 31.8056416463794}, {"key": "good_oil_api_bias", "tol": 0.05, "unit": "API", "label": "Gravity minus the lab value", "expected": -8.894358353620603}]'::jsonb
     where app_slug = 'fluid' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book fluid refused: fluid/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3f7abe6a61283cb6be5c4066abffda2a' and fields = '[{"key": "good_oil_c7plus_tc_r", "tol": 0.05, "unit": "degR", "label": "C7+ critical temperature", "expected": 1324.2385574932478}, {"key": "good_oil_untuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Untuned saturation pressure", "expected": 2791.100735294379}, {"key": "good_oil_psat_bias_pct", "tol": 0.02, "unit": "percent", "label": "Saturation pressure above the lab value", "expected": 5.938198064045652}, {"key": "good_oil_untuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Untuned total gas-oil ratio", "expected": 793.8042771796476}, {"key": "good_oil_untuned_sto_api", "tol": 0.05, "unit": "API", "label": "Untuned stock tank gravity", "expected": 31.8056416463794}, {"key": "good_oil_api_bias", "tol": 0.05, "unit": "API", "label": "Gravity minus the lab value", "expected": -8.894358353620603}]'::jsonb) from public.academy_capstones where app_slug = 'fluid' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book fluid refused: fluid/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Tune the compositional model to the Good Oil Co. Well No. 4 study and report both the result and its price. Regress the four bounded knobs on the C7+ pseudo-component and NOTHING else, jointly against all four measurements at once: the saturation pressure of 2634.65 psia at 220 F, and the total gas-oil ratio of 768 scf/stb, the stock tank gravity of 40.7 API and the formation volume factor of 1.474 rb/stb from the optimum separator test at 114.65 psia and 75 F, with the stock tank stage at 14.65 psia and 75 F appended to it. Report the saturation pressure, the total gas-oil ratio and the stock tank gravity the TUNED model produces; the values the regression lands on for the C7+ volume shift and for the C1 to C7+ binary interaction parameter; and the factor by which the sum of squared residuals falls, being the value before the fit divided by the value after it. Every field asks for a value AFTER the regression.',
           fields = '[{"key": "good_oil_tuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Tuned saturation pressure", "expected": 2632.64216695564}, {"key": "good_oil_tuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Tuned total gas-oil ratio", "expected": 761.7262989883229}, {"key": "good_oil_tuned_sto_api", "tol": 0.05, "unit": "API", "label": "Tuned stock tank gravity", "expected": 38.755039373806255}, {"key": "tuned_splus_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C7+ volume shift", "expected": 0.12266364195926757}, {"key": "tuned_kc1_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C1 to C7+ interaction parameter", "expected": 0.050325447877585576}, {"key": "tuning_ssr_reduction", "tol": 0.05, "unit": "times", "label": "Residual reduction factor", "expected": 23.157104602764026}]'::jsonb
     where app_slug = 'fluid' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book fluid refused: fluid/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '332a0e7774027e1383ae1316983e822f' and fields = '[{"key": "good_oil_tuned_psat_psia", "tol": 0.5, "unit": "psia", "label": "Tuned saturation pressure", "expected": 2632.64216695564}, {"key": "good_oil_tuned_gor_scf_stb", "tol": 1, "unit": "scf/stb", "label": "Tuned total gas-oil ratio", "expected": 761.7262989883229}, {"key": "good_oil_tuned_sto_api", "tol": 0.05, "unit": "API", "label": "Tuned stock tank gravity", "expected": 38.755039373806255}, {"key": "tuned_splus_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C7+ volume shift", "expected": 0.12266364195926757}, {"key": "tuned_kc1_knob", "tol": 0.0005, "unit": "-", "label": "Tuned C1 to C7+ interaction parameter", "expected": 0.050325447877585576}, {"key": "tuning_ssr_reduction", "tol": 0.05, "unit": "times", "label": "Residual reduction factor", "expected": 23.157104602764026}]'::jsonb) from public.academy_capstones where app_slug = 'fluid' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book fluid refused: fluid/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book fluid: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
